export function slugify(s: string): string {
  return s.toLowerCase().replace(/ /g, '-');
}

// REFACTOR: melhorar sem quebrar
export function slugify(s: string): string {
  return s
    .toLowerCase()
    .trim()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // remove accents
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}
